head.script:
scwin.onpageload = function () {
    // 예제 테스트를 위한 초기화
    scwin.initializeExample();
};

// 예제 테스트를 위한 초기화
scwin.initializeExample = function () {
    // InputCalenar 'ica_exam1'에 초기 값 설정
    ica_exam1.setValue("20250101");
};

/**
 * 버튼 "AddDate"의 onclick 이벤트
 */
scwin.btn_addDate_onclick = function (e) {
    var _result = "";

    // InputCalendar에서 받은 "yyyyMMdd" 형식의 날짜
    var _date = ica_exam1.getValue();

    // Input에서 받은 더할 숫자
    var _offset = ipt_num.getValue() || 0;

    // "yyyyMMdd" 형식의 날짜와 더할 일 수를 입력받아 더한 날짜를 반환합니다. 더할 값은 음수도 가능합니다.
    _result = WebSquare.date.dateAdd(_date, _offset);

    // 로그 출력
    let strLog = "Date: " + _date + ", Offset: " + _offset + ", Result: " + _result;
    $c.frame.printExampleLog(strLog, txa_log, false);
    console.log(strLog);
};


/**
 * textarea의 로그 삭제
 */
scwin.btn_clearLog_onclick = function (e) {
    let strTargetId = this.getUserData("userData1");
    let cmpTarget;
    if (strTargetId) {
        cmpTarget = $p.getComponentById(strTargetId) || txa_log;
    } else {
        cmpTarget = txa_log;
    }
    //textarea value를 빈문자열로 할당.
    cmpTarget.setValue("");
};
